<script>
let boot={},prov={},focusIndex=0,pendingLaunch=null;
const providerNames={netflix:'Netflix',iplayer:'BBC iPlayer',itvx:'ITVX',channel4:'Channel 4',disney:'Disney+',primevideo:'Prime Video'};
const pEl=document.getElementById('programmes'),sEl=document.getElementById('providers'),statusEl=document.getElementById('status'),modalWrap=document.getElementById('modalWrap'),modal=document.getElementById('modal');
function esc(s){return String(s??'').replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]))}
function cards(){return [...document.querySelectorAll('.nav')]}function focusCard(i){const c=cards();if(!c.length)return;focusIndex=(i+c.length)%c.length;c[focusIndex].focus()}
async function api(path,opt={}){const r=await fetch('http://127.0.0.1:8765'+path,{headers:{'Content-Type':'application/json'},...opt});if(!r.ok)throw new Error(await r.text());return await r.json()}
function show(html){modal.innerHTML=html;modalWrap.classList.add('show');const f=modal.querySelector('input,select,button');if(f)f.focus()}function closeModal(){modalWrap.classList.remove('show')}
function renderProgrammes(){const rows=boot.programmes||[];pEl.innerHTML='';if(!rows.length){pEl.innerHTML='<div class="empty">No favourites yet. Choose <b>Add Programme</b> to create your local watch list.</div>';return}rows.slice(0,10).forEach(p=>{const d=document.createElement('div');d.className='card nav';d.tabIndex=0;d.dataset.programme=p.id;const ep=(p.season||p.episode)?('S'+(p.season??'?')+' E'+(p.episode??'?')):'Ready to watch';const prog=p.duration?Math.min(100,Math.round((p.progress_position||0)*100/p.duration))+'% watched':(p.completed?'Watched':'');d.innerHTML='<div><span class="badge '+(p.new_release?'new':'')+'">'+esc(p.new_release?'NEW • '+(providerNames[p.provider]||p.provider):(providerNames[p.provider]||p.provider))+'</span><br><br><strong>'+esc(p.title)+'</strong></div><small>'+esc(ep)+(prog?' • '+esc(prog):'')+'</small>';pEl.appendChild(d)})}
function renderProviders(){sEl.innerHTML='';Object.entries(boot.providers||{}).forEach(([k,p])=>{const d=document.createElement('div');d.className='card nav';d.tabIndex=0;d.dataset.provider=k;d.innerHTML='<strong>'+esc(providerNames[k]||p.name||k)+'</strong><small>Open service</small>';sEl.appendChild(d)})}
async function load(){try{boot=await api('/api/ui/bootstrap');prov=boot.provisioning||{};document.documentElement.style.setProperty('--scale',(prov.ui_scale||100)/100);document.getElementById('profileLabel').textContent='Profile: '+(prov.profile||'default');renderProgrammes();renderProviders();statusEl.textContent='Veyra '+boot.version+' • Ready';if(!prov.complete)firstRun()}catch(e){statusEl.textContent='Core unavailable • View remains alive'}}
function firstRun(){show('<h2>Welcome to Veyra</h2><p>Set the local viewer profile and appliance name. Provider logins remain in their own persistent browser profiles.</p><div class="field"><label>Viewer profile</label><input id="pname" value="'+esc(prov.profile||'default')+'"></div><div class="field"><label>Device name</label><input id="dname" value="'+esc(prov.device_name||'Veyra TV')+'"></div><div class="buttons"><button class="btn primary" onclick="finishFirstRun()">Continue</button></div>')}
async function finishFirstRun(){prov=await api('/api/provisioning',{method:'POST',body:JSON.stringify({profile:document.getElementById('pname').value||'default',device_name:document.getElementById('dname').value||'Veyra TV',complete:true})});closeModal();await load();setTimeout(()=>focusCard(0),150)}
document.addEventListener('keydown',e=>{if(modalWrap.classList.contains('show')){if(e.key==='Escape'){e.preventDefault();closeModal()}return}if(e.key==='ArrowRight'||e.key==='ArrowDown'){e.preventDefault();focusCard(focusIndex+1)}if(e.key==='ArrowLeft'||e.key==='ArrowUp'){e.preventDefault();focusCard(focusIndex-1)}if(e.key==='Enter'){const a=document.activeElement;if(a?.dataset.programme)playProgramme(a.dataset.programme);else if(a?.dataset.provider)openProvider(a.dataset.provider);else if(a?.dataset.action)action(a.dataset.action)}});
document.addEventListener('click',e=>{const x=e.target.closest('.card');if(!x)return;if(x.dataset.programme)playProgramme(x.dataset.programme);else if(x.dataset.provider)openProvider(x.dataset.provider);else if(x.dataset.action)action(x.dataset.action)});
async function playProgramme(id){const r=await api('/api/programmes/'+encodeURIComponent(id)+'/play',{method:'POST'});if(r.requires_acknowledgement){pendingLaunch={type:'programme',id};showLicence()}}
async function openProvider(k){const p=boot.providers[k];if(!p)return;const r=await api('/api/launch',{method:'POST',body:JSON.stringify({provider:k,url:p.home_url,profile:prov.profile||'default'})});if(r.requires_acknowledgement){pendingLaunch={type:'provider',provider:k,url:p.home_url};showLicence()}}
function showLicence(){show('<h2>UK TV Licence reminder</h2><p>A valid UK TV Licence is required for BBC iPlayer viewing and for watching live television or live streamed broadcasts in the UK.</p><label><input style="width:auto" type="checkbox" id="licAck"> I understand and do not need this reminder again for this profile.</label><div class="buttons"><button class="btn" onclick="closeModal()">Cancel</button><button class="btn primary" onclick="ackAndContinue()">Continue</button></div>')}
async function ackAndContinue(){if(document.getElementById('licAck').checked)await api('/api/compliance/uk-tv-licence',{method:'POST',body:JSON.stringify({profile:prov.profile||'default',acknowledged:true})});const p=pendingLaunch;pendingLaunch=null;closeModal();if(!p)return;if(p.type==='programme')await playProgramme(p.id);else await openProvider(p.provider)}
function addProgramme(){let opts=Object.keys(boot.providers||{}).map(k=>'<option value="'+esc(k)+'">'+esc(providerNames[k]||k)+'</option>').join('');show('<h2>Add to My Programmes</h2><div class="field"><label>Programme title</label><input id="ptitle"></div><div class="field"><label>Playback service</label><select id="pprovider">'+opts+'</select></div><div class="field"><label>Programme / episode URL</label><input id="purl" placeholder="https://…"></div><div class="field"><label>Season</label><input id="pseason" inputmode="numeric"></div><div class="field"><label>Episode</label><input id="pepisode" inputmode="numeric"></div><div class="buttons"><button class="btn" onclick="closeModal()">Cancel</button><button class="btn primary" onclick="saveProgramme()">Save</button></div>')}
async function saveProgramme(){const body={title:document.getElementById('ptitle').value,provider:document.getElementById('pprovider').value,url:document.getElementById('purl').value,season:Number(document.getElementById('pseason').value)||null,episode:Number(document.getElementById('pepisode').value)||null};await api('/api/programmes',{method:'POST',body:JSON.stringify(body)});closeModal();await load();focusCard(0)}
async function action(a){if(a==='add')return addProgramme();if(a==='local'){const d=await api('/api/local/discover');show('<h2>Local media</h2><div class="notice">'+((d.servers||[]).length?esc((d.servers||[]).map(x=>x.name).join(', ')):'No local media server found.')+'</div><div class="buttons"><button class="btn primary" onclick="closeModal()">Done</button></div>')}if(a==='overlaytest')await api('/api/overlay',{method:'POST',body:JSON.stringify({kind:'banner',title:'Veyra Overlay',message:'Local overlay test passed.',duration:6,position:'top-right'})});if(a==='settings')settings();if(a==='diagnostics')diagnostics()}
async function settings(){const a=await api('/api/audio/sinks');let opts=(a.sinks||[]).map(s=>'<option value="'+esc(s.id)+'">'+esc(s.name)+(s.default?' (current)':'')+'</option>').join('');show('<h2>Settings</h2><div class="field"><label>Viewer profile</label><input id="setProfile" value="'+esc(prov.profile||'default')+'"></div><div class="field"><label>UI scale</label><select id="setScale">'+[90,100,110,120,130].map(x=>'<option '+((prov.ui_scale||100)==x?'selected':'')+'>'+x+'</option>').join('')+'</select></div><div class="field"><label>Audio output</label><select id="setSink"><option value="">Keep current</option>'+opts+'</select></div><div class="buttons"><button class="btn" onclick="closeModal()">Cancel</button><button class="btn primary" onclick="saveSettings()">Save</button></div>')}
async function saveSettings(){const sink=document.getElementById('setSink').value;if(sink)await api('/api/audio/default',{method:'POST',body:JSON.stringify({sink})});await api('/api/provisioning',{method:'POST',body:JSON.stringify({profile:document.getElementById('setProfile').value||'default',ui_scale:Number(document.getElementById('setScale').value)})});location.reload()}
async function diagnostics(){const d=await api('/api/diagnostics');show('<h2>Diagnostics</h2><div class="notice"><pre>'+esc(JSON.stringify(d,null,2))+'</pre></div><div class="buttons"><button class="btn" onclick="adminConsole()">Administrative Console</button><button class="btn primary" onclick="closeModal()">Done</button></div>')}
async function adminConsole(){const st=await api('/api/admin-console/status');if(!st.configured){show('<h2>Create maintenance PIN</h2><div class="field"><input id="newPin" type="password" inputmode="numeric"></div><div class="buttons"><button class="btn" onclick="closeModal()">Cancel</button><button class="btn primary" onclick="adminSetPin()">Save PIN</button></div>');return}show('<h2>Administrative Console</h2><p>This hands the local display to the jnsadmin console. Type veyra-return or exit to return.</p><div class="field"><input id="adminPin" type="password" inputmode="numeric"></div><div class="buttons"><button class="btn" onclick="closeModal()">Cancel</button><button class="btn primary" onclick="adminUnlock()">Open Console</button></div>')}
async function adminSetPin(){const pin=document.getElementById('newPin').value;await api('/api/admin-console/set-pin',{method:'POST',body:JSON.stringify({pin})});adminConsole()}
async function adminUnlock(){const pin=document.getElementById('adminPin').value;await api('/api/admin-console/open',{method:'POST',body:JSON.stringify({pin})});show('<h2>Opening Administrative Console…</h2>')}
function renderOverlay(m){if(m.suppressed)return;const d=document.createElement('div');d.className='ov '+(m.position||'top-right');d.innerHTML='<b>'+esc(m.title||'')+'</b><br>'+esc(m.message||'');document.getElementById('overlay').appendChild(d);setTimeout(()=>d.remove(),(m.duration||10)*1000)}
function connect(){const ws=new WebSocket('ws://'+location.host+'/ws');ws.onmessage=e=>{const m=JSON.parse(e.data);if(m.type==='overlay')renderOverlay(m.payload)};ws.onclose=()=>setTimeout(connect,750)}
connect();load().then(()=>setTimeout(()=>focusCard(0),300));
</script></body></html>'''

@app.get("/")
async def root(): return HTMLResponse(HTML)

@app.get("/health")
async def health():
    return {"status":"ok","version":__version__,"clients":len(clients),"uptime_s":int(time.monotonic()-started)}

@app.post("/internal/command")
async def command(payload: dict, x_veyra_token: str | None = Header(default=None)):
    if x_veyra_token != SETTINGS.view_token:
        raise HTTPException(403, "forbidden")
    dead=[]; message=json.dumps(payload)
    for ws in list(clients):
        try: await ws.send_text(message)
        except Exception: dead.append(ws)
    for ws in dead: clients.discard(ws)
    return {"ok":True,"clients":len(clients)}

@app.websocket("/ws")
async def ws_endpoint(ws: WebSocket):
    await ws.accept(); clients.add(ws)
    try:
        while True: await ws.receive_text()
    except (WebSocketDisconnect, Exception): clients.discard(ws)

